use std::cell::RefCell;
use std::rc::{Rc, Weak};

#[derive(Debug)]
pub struct BOSTree {
    pub root_node: Option<Rc<RefCell<BOSNode>>>,
    pub cmp_function: BOSTreeCmpFunction,
    pub free_function: Option<BOSTreeFreeFunction>,
}

#[derive(Debug)]
pub struct BOSNode {
    pub left_child_count: u32,
    pub right_child_count: u32,
    pub depth: u32,
    pub left_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub right_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub parent_node: Option<Weak<RefCell<BOSNode>>>,
    pub key: String,
    pub data: Option<String>,
    pub weak_ref_count: u8,
    pub weak_ref_node_valid: u8,
}

pub type BOSTreeCmpFunction = fn(&str, &str) -> i32;
pub type BOSTreeFreeFunction = fn(&Rc<RefCell<BOSNode>>);

fn imax(i1: u32, i2: u32) -> u32 {
    if i1 > i2 { i1 } else { i2 }
}

fn balance(node: &Rc<RefCell<BOSNode>>) -> i32 {
    let n = node.borrow();
    let left_depth = n.left_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1);
    let right_depth = n.right_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1);
    right_depth as i32 - left_depth as i32
}

fn rotate_right(tree: &mut BOSTree, p: Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let l = p.borrow().left_child_node.clone().unwrap();
    {
        let p_b = &mut *p.borrow_mut();
        if let Some(ref parent_weak) = p_b.parent_node {
            if let Some(parent) = parent_weak.upgrade() {
                let mut pb = parent.borrow_mut();
                if pb.left_child_node.as_ref().map_or(false, |x| Rc::ptr_eq(x, &p)) {
                    pb.left_child_node = Some(l.clone());
                } else {
                    pb.right_child_node = Some(l.clone());
                }
            }
        } else {
            tree.root_node = Some(l.clone());
        }
    }
    let l_right = l.borrow().right_child_node.clone();
    let l_right_count = l.borrow().right_child_count;
    {
        let mut lb = l.borrow_mut();
        lb.parent_node = p.borrow().parent_node.clone();
    }
    {
        let mut pb = p.borrow_mut();
        pb.left_child_node = l_right.clone();
        pb.left_child_count = l_right_count;
        if let Some(ref lr) = l_right {
            lr.borrow_mut().parent_node = Rc::downgrade(&p);
        }
        pb.depth = imax(
            pb.left_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1),
            pb.right_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1),
        );
    }
    {
        let mut lb = l.borrow_mut();
        lb.right_child_node = Some(p.clone());
        let p_lc = p.borrow().left_child_count;
        let p_rc = p.borrow().right_child_count;
        lb.right_child_count = p_lc + p_rc + 1;
        lb.depth = imax(
            lb.left_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1),
            lb.right_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1),
        );
    }
    p.borrow_mut().parent_node = Rc::downgrade(&l);
    l
}
