                if let Some(ref pw) = node_parent {
                    if let Some(p) = pw.upgrade() {
                        if p.borrow().left_child_node.as_ref().map_or(false, |x| Rc::ptr_eq(x, node)) {
                            p.borrow_mut().left_child_node = Some(candidate.clone());
                        } else {
                            p.borrow_mut().right_child_node = Some(candidate.clone());
