                    lc.borrow_mut().parent_node = None;
                } else if node.borrow().right_child_node.is_some() {
                    let rc = node.borrow().right_child_node.clone().unwrap();
                    self.root_node = Some(rc.clone());
                    rc.borrow_mut().parent_node = None;
                } else {
                    self.root_node = None;
                }
                bubble_up = None;
            } else {
                let parent = node_parent.unwrap().upgrade().unwrap();
                let candidate = node.borrow().left_child_node.clone().or_else(|| node.borrow().right_child_node.clone());
                let candidate_count = candidate.as_ref().map_or(0, |c| c.borrow().left_child_count + c.borrow().right_child_count + 1);

                if parent.borrow().left_child_node.as_ref().map_or(false, |x| Rc::ptr_eq(x, node)) {
                    parent.borrow_mut().left_child_node = candidate.clone();
                    parent.borrow_mut().left_child_count = candidate_count;
                } else {
                    parent.borrow_mut().right_child_node = candidate.clone();
                    parent.borrow_mut().right_child_count = candidate_count;
                }
                if let Some(ref c) = candidate {
                    c.borrow_mut().parent_node = Rc::downgrade(&parent);
                }
                bubble_up = Some(parent);
            }
        }

        // Rebalance up to root
        let mut bubbling_finished = false;
        let mut bu = bubble_up;
        while let Some(b) = bu {
            if !bubbling_finished {
                let left_depth = b.borrow().left_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1);
                let right_depth = b.borrow().right_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1);
                let max_depth = imax(left_depth, right_depth);
                let depth_changed = b.borrow().depth != max_depth;
                b.borrow_mut().depth = max_depth;

                if left_depth as i32 + 2 == right_depth as i32 {
                    if b.borrow().right_child_node.as_ref().map_or(false, |rc| balance(rc) < 0) {
                        let rc = b.borrow().right_child_node.clone().unwrap();
                        rotate_right(self, rc);
