    pub fn bostree_remove(&mut self, node: &Rc<RefCell<BOSNode>>) {
        let bubble_up: Option<Rc<RefCell<BOSNode>>>;
        let has_left = node.borrow().left_child_node.is_some();
        let has_right = node.borrow().right_child_node.is_some();

        if has_left && has_right {
            let left_depth = node.borrow().left_child_node.as_ref().map_or(0, |c| c.borrow().depth);
            let right_depth = node.borrow().right_child_node.as_ref().map_or(0, |c| c.borrow().depth);
            let candidate: Rc<RefCell<BOSNode>>;
            let bubble_start: Rc<RefCell<BOSNode>>;

            if left_depth >= right_depth {
                node.borrow_mut().left_child_count -= 1;
                let mut c = node.borrow().left_child_node.clone().unwrap();
                loop {
                    let next = c.borrow().right_child_node.clone();
                    match next {
                        Some(n) => { c.borrow_mut().right_child_count -= 1; c = n; }
                        None => break
                    }
                }
                candidate = c;
                let lost_child = candidate.borrow().left_child_node.clone();
                bubble_start = candidate.borrow().parent_node.as_ref().and_then(|w| w.upgrade()).unwrap();
                if is_left_child(&bubble_start, &candidate) {
                    bubble_start.borrow_mut().left_child_node = lost_child;
                } else {
                    bubble_start.borrow_mut().right_child_node = lost_child;
                }
                if let Some(ref lc) = candidate.borrow().left_child_node {
                    lc.borrow_mut().parent_node = Some(Rc::downgrade(&bubble_start));
                }
            } else {
                node.borrow_mut().right_child_count -= 1;
                let mut c = node.borrow().right_child_node.clone().unwrap();
                loop {
                    let next = c.borrow().left_child_node.clone();
                    match next {
                        Some(n) => { c.borrow_mut().left_child_count -= 1; c = n; }
                        None => break
                    }
                }
                candidate = c;
                let lost_child = candidate.borrow().right_child_node.clone();
                bubble_start = candidate.borrow().parent_node.as_ref().and_then(|w| w.upgrade()).unwrap();
                if is_left_child(&bubble_start, &candidate) {
                    bubble_start.borrow_mut().left_child_node = lost_child;
                } else {
                    bubble_start.borrow_mut().right_child_node = lost_child;
                }
                if let Some(ref rc) = candidate.borrow().right_child_node {
                    rc.borrow_mut().parent_node = Some(Rc::downgrade(&bubble_start));
                }
            }

            let node_parent = node.borrow().parent_node.clone();
            if let Some(ref pw) = node_parent {
                if let Some(p) = pw.upgrade() {
                    if is_left_child(&p, node) {
                        p.borrow_mut().left_child_node = Some(candidate.clone());
                    } else {
                        p.borrow_mut().right_child_node = Some(candidate.clone());
                    }
                }
            } else {
                self.root_node = Some(candidate.clone());
            }
            candidate.borrow_mut().parent_node = node_parent;

            let node_left = node.borrow().left_child_node.clone();
            let node_lc = node.borrow().left_child_count;
            let node_right = node.borrow().right_child_node.clone();
            let node_rc = node.borrow().right_child_count;
            candidate.borrow_mut().left_child_node = node_left.clone();
            candidate.borrow_mut().left_child_count = node_lc;
            candidate.borrow_mut().right_child_node = node_right.clone();
            candidate.borrow_mut().right_child_count = node_rc;
            if let Some(ref nl) = node_left { nl.borrow_mut().parent_node = Some(Rc::downgrade(&candidate)); }
            if let Some(ref nr) = node_right { nr.borrow_mut().parent_node = Some(Rc::downgrade(&candidate)); }

            if !Rc::ptr_eq(&bubble_start, node) {
                let mut bs = bubble_start;
                while !Rc::ptr_eq(&bs, &candidate) {
                    let ld = bs.borrow().left_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1);
                    let rd = bs.borrow().right_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1);
                    bs.borrow_mut().depth = imax(ld, rd);
                    let bal = rd as i32 - ld as i32;
                    if bal > 1 {
                        let rc = bs.borrow().right_child_node.clone().unwrap();
                        if node_balance(&rc) < 0 { rotate_right(self, rc); }
                        bs = rotate_left(self, bs);
                    } else if bal < -1 {
                        let lc = bs.borrow().left_child_node.clone().unwrap();
                        if node_balance(&lc) > 0 { rotate_left(self, lc); }
                        bs = rotate_right(self, bs);
                    } else {
                        bs = bs.borrow().parent_node.as_ref().and_then(|w| w.upgrade()).unwrap();
                    }
                }
            }

            let ld = candidate.borrow().left_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1);
            let rd = candidate.borrow().right_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1);
            candidate.borrow_mut().depth = imax(ld, rd);

            bubble_up = candidate.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            if let Some(ref bu) = bubble_up {
                if is_left_child(bu, &candidate) {
                    bu.borrow_mut().left_child_count -= 1;
                } else {
                    bu.borrow_mut().right_child_count -= 1;
                }
            }
        } else {
            let node_parent = node.borrow().parent_node.clone();
            if node_parent.is_none() {
                if node.borrow().left_child_node.is_some() {
                    let lc = node.borrow().left_child_node.clone().unwrap();
                    self.root_node = Some(lc.clone());
                    lc.borrow_mut().parent_node = None;
                } else if node.borrow().right_child_node.is_some() {
                    let rc = node.borrow().right_child_node.clone().unwrap();
                    self.root_node = Some(rc.clone());
                    rc.borrow_mut().parent_node = None;
                } else {
                    self.root_node = None;
                }
                bubble_up = None;
            } else {
                let parent = node_parent.unwrap().upgrade().unwrap();
                let candidate = node.borrow().left_child_node.clone().or_else(|| node.borrow().right_child_node.clone());
                let cc = candidate.as_ref().map_or(0, |c| c.borrow().left_child_count + c.borrow().right_child_count + 1);
                if is_left_child(&parent, node) {
                    parent.borrow_mut().left_child_node = candidate.clone();
                    parent.borrow_mut().left_child_count = cc;
                } else {
                    parent.borrow_mut().right_child_node = candidate.clone();
                    parent.borrow_mut().right_child_count = cc;
                }
                if let Some(ref c) = candidate { c.borrow_mut().parent_node = Some(Rc::downgrade(&parent)); }
                bubble_up = Some(parent);
            }
        }

        let mut bubbling_finished = false;
        let mut bu = bubble_up;
        while let Some(b) = bu {
            if !bubbling_finished {
                let ld = b.borrow().left_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1);
                let rd = b.borrow().right_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1);
                let md = imax(ld, rd);
                let depth_changed = b.borrow().depth != md;
                b.borrow_mut().depth = md;
                if ld as i32 + 2 == rd as i32 {
                    let rc = b.borrow().right_child_node.clone().unwrap();
                    if node_balance(&rc) < 0 { rotate_right(self, rc); }
                    bu = Some(rotate_left(self, b));
                } else if ld as i32 == rd as i32 + 2 {
                    let lc = b.borrow().left_child_node.clone().unwrap();
                    if node_balance(&lc) > 0 { rotate_left(self, lc); }
                    bu = Some(rotate_right(self, b));
                } else {
                    if !depth_changed { bubbling_finished = true; }
                }
            }
            let b_ref = bu.unwrap();
            let bp = b_ref.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            if let Some(ref bp_ref) = bp {
                if is_left_child(bp_ref, &b_ref) {
                    bp_ref.borrow_mut().left_child_count -= 1;
                } else {
                    bp_ref.borrow_mut().right_child_count -= 1;
                }
            }
            bu = bp;
        }

        node.borrow_mut().weak_ref_node_valid = 0;
        self.bostree_node_weak_unref(node);
    }
