            if node_parent.is_none() {
                if node.borrow().left_child_node.is_some() {
                    let lc = node.borrow().left_child_node.clone().unwrap();
                    self.root_node = Some(lc.clone());
                    lc.borrow_mut().parent_node = None;
                } else if node.borrow().right_child_node.is_some() {
                    let rc = node.borrow().right_child_node.clone().unwrap();
                    self.root_node = Some(rc.clone());
                    rc.borrow_mut().parent_node = None;
                } else {
                    self.root_node = None;
                }
                bubble_up = None;
            } else {
                let parent = node_parent.unwrap().upgrade().unwrap();
                let candidate = node.borrow().left_child_node.clone().or_else(|| node.borrow().right_child_node.clone());
                let cc = candidate.as_ref().map_or(0, |c| c.borrow().left_child_count + c.borrow().right_child_count + 1);
                if is_left_child(&parent, node) {
                    parent.borrow_mut().left_child_node = candidate.clone();
                    parent.borrow_mut().left_child_count = cc;
                } else {
                    parent.borrow_mut().right_child_node = candidate.clone();
                    parent.borrow_mut().right_child_count = cc;
                }
                if let Some(ref c) = candidate { c.borrow_mut().parent_node = Some(Rc::downgrade(&parent)); }
                bubble_up = Some(parent);
            }
        }

        let mut bubbling_finished = false;
        let mut bu = bubble_up;
        while bu.is_some() {
            let b = bu.as_ref().unwrap().clone();
            if !bubbling_finished {
                let ld = b.borrow().left_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1);
                let rd = b.borrow().right_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1);
                let md = imax(ld, rd);
                let depth_changed = b.borrow().depth != md;
                b.borrow_mut().depth = md;
                if ld as i32 + 2 == rd as i32 {
                    let rc = b.borrow().right_child_node.clone().unwrap();
                    if node_balance(&rc) < 0 { rotate_right(self, rc); }
                    bu = Some(rotate_left(self, b));
                } else if ld as i32 == rd as i32 + 2 {
                    let lc = b.borrow().left_child_node.clone().unwrap();
                    if node_balance(&lc) > 0 { rotate_left(self, lc); }
                    bu = Some(rotate_right(self, b));
                } else {
                    if !depth_changed { bubbling_finished = true; }
                }
            }
            let b_ref = bu.as_ref().unwrap().clone();
            let bp = b_ref.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            if let Some(ref bp_ref) = bp {
                if is_left_child(bp_ref, &b_ref) {
                    bp_ref.borrow_mut().left_child_count -= 1;
                } else {
                    bp_ref.borrow_mut().right_child_count -= 1;
                }
            }
            bu = bp;
        }

        node.borrow_mut().weak_ref_node_valid = 0;
        self.bostree_node_weak_unref(node);
    }
