            let nb = n.borrow(); nb.left_child_count + nb.right_child_count + 1
        })
    }

    pub fn bostree_insert(&mut self, key: String, data: Option<String>) -> Rc<RefCell<BOSNode>> {
        let new_node = Rc::new(RefCell::new(BOSNode {
            left_child_count: 0, right_child_count: 0, depth: 0,
            left_child_node: None, right_child_node: None, parent_node: None,
            key, data, weak_ref_count: 1, weak_ref_node_valid: 1,
        }));
        let mut parent_node: Option<Rc<RefCell<BOSNode>>> = None;
        let mut current = self.root_node.clone();
        while let Some(cur) = current {
            parent_node = Some(cur.clone());
            let cmp = (self.cmp_function)(&new_node.borrow().key, &cur.borrow().key);
            if cmp < 0 {
                cur.borrow_mut().left_child_count += 1;
                current = cur.borrow().left_child_node.clone();
            } else {
                cur.borrow_mut().right_child_count += 1;
                current = cur.borrow().right_child_node.clone();
            }
        }
        new_node.borrow_mut().parent_node = parent_node.as_ref().map(|p| Rc::downgrade(p));
        if let Some(ref parent) = parent_node {
            let is_left = (self.cmp_function)(&new_node.borrow().key, &parent.borrow().key) < 0;
            if is_left { parent.borrow_mut().left_child_node = Some(new_node.clone()); }
            else { parent.borrow_mut().right_child_node = Some(new_node.clone()); }
        } else {
            self.root_node = Some(new_node.clone());
            return new_node;
        }
        let parent = parent_node.unwrap();
        let has_left = parent.borrow().left_child_node.is_some();
        let has_right = parent.borrow().right_child_node.is_some();
        if has_left ^ has_right {
            parent.borrow_mut().depth += 1;
            let mut p = parent;
            loop {
                let pp = p.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                let pp = match pp { Some(x) => x, None => break };
                let new_ld = depth_of(&pp.borrow().left_child_node);
                let new_rd = depth_of(&pp.borrow().right_child_node);
                let max_d = imax(new_ld, new_rd);
                if pp.borrow().depth != max_d { pp.borrow_mut().depth = max_d; } else { break; }
                if new_ld as i32 - 2 == new_rd as i32 {
                    let lc = pp.borrow().left_child_node.clone().unwrap();
                    if node_balance(&lc) > 0 { rotate_left(self, lc); }
                    p = rotate_right(self, pp);
                } else if new_ld as i32 + 2 == new_rd as i32 {
                    let rc = pp.borrow().right_child_node.clone().unwrap();
                    if node_balance(&rc) < 0 { rotate_right(self, rc); }
                    p = rotate_left(self, pp);
                } else { p = pp; }
            }
        }
        new_node
    }
