    pub fn bostree_node_weak_unref(&mut self, node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
        node.borrow_mut().weak_ref_count -= 1;
        if node.borrow().weak_ref_count == 0 {
            if let Some(f) = self.free_function { f(node); }
            None
        } else if node.borrow().weak_ref_node_valid != 0 {
            Some(node.clone())
        } else {
            None
        }
    }

    pub fn bostree_lookup(&self, key: &str) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        while let Some(cur) = current {
            let cmp = (self.cmp_function)(key, &cur.borrow().key);
            if cmp == 0 { return Some(cur); }
            else if cmp < 0 { current = cur.borrow().left_child_node.clone(); }
            else { current = cur.borrow().right_child_node.clone(); }
        }
        None
    }

    pub fn bostree_select(&self, index: u32) -> Option<Rc<RefCell<BOSNode>>> {
        let mut current = self.root_node.clone();
        let mut idx = index;
        while let Some(cur) = current {
            let lc = cur.borrow().left_child_count;
            if lc <= idx {
                idx -= lc;
                if idx == 0 { return Some(cur); }
                idx -= 1;
                current = cur.borrow().right_child_node.clone();
            } else {
                current = cur.borrow().left_child_node.clone();
            }
        }
        None
    }

    #[cfg(debug_assertions)]
    pub fn bostree_print(&self) {
        fn print_helper(node: &Rc<RefCell<BOSNode>>) {
            let nb = node.borrow();
            println!("  {} [label=\\N ({},{},{})];", nb.key, nb.left_child_count, nb.right_child_count, nb.depth);
            if let Some(ref pw) = nb.parent_node {
                if let Some(p) = pw.upgrade() { println!("  {} -> {} [color=green];", nb.key, p.borrow().key); }
            }
            if let Some(ref left) = nb.left_child_node { println!("  {} -> {}", nb.key, left.borrow().key); print_helper(left); }
            if let Some(ref right) = nb.right_child_node { println!("  {} -> {}", nb.key, right.borrow().key); print_helper(right); }
        }
        if self.root_node.is_none() { return; }
        println!("digraph {{  ordering = out;");
        print_helper(self.root_node.as_ref().unwrap());
        println!("}}");
    }
}

pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    node.borrow_mut().weak_ref_count += 1;
    node.clone()
}

pub fn bostree_next_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if node.borrow().right_child_node.is_some() {
        let mut n = node.borrow().right_child_node.clone().unwrap();
        while n.borrow().left_child_node.is_some() {
            let next = n.borrow().left_child_node.clone().unwrap();
            n = next;
        }
        Some(n)
    } else {
        let mut n = node.clone();
        loop {
            let parent = n.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            match parent {
                Some(p) => {
                    let is_right = p.borrow().right_child_node.as_ref().map_or(false, |r| Rc::ptr_eq(r, &n));
                    if is_right { n = p; } else { return Some(p); }
                }
                None => return None
            }
        }
    }
}

pub fn bostree_previous_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if node.borrow().left_child_node.is_some() {
        let mut n = node.borrow().left_child_node.clone().unwrap();
        while n.borrow().right_child_node.is_some() {
            let next = n.borrow().right_child_node.clone().unwrap();
            n = next;
        }
        Some(n)
    } else {
        let mut n = node.clone();
        loop {
            let parent = n.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            match parent {
                Some(p) => {
                    let is_left = p.borrow().left_child_node.as_ref().map_or(false, |l| Rc::ptr_eq(l, &n));
                    if is_left { n = p; } else { return Some(p); }
                }
                None => return None
            }
        }
    }
}

pub fn bostree_rank(node: &Rc<RefCell<BOSNode>>) -> u32 {
    let mut counter = node.borrow().left_child_count;
    let mut n = node.clone();
    loop {
        let parent = n.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
        match parent {
            Some(p) => {
                let is_right = p.borrow().right_child_node.as_ref().map_or(false, |r| Rc::ptr_eq(r, &n));
                if is_right { counter += 1 + p.borrow().left_child_count; }
                n = p;
            }
            None => break
        }
    }
    counter
}
